/**
 * Brief civilization descriptions for the territory info card.
 * Shown when a user clicks a territory on the globe.
 */

export interface CivDescription {
  summary: string;
  detail?: string;
  knownFor: string;
  keyFacts?: string[];
  /** Optional — omitted (rather than pointing at a dead hotlink or a
   *  mismatched civilization's photo) when no correct local asset exists.
   *  Consumers should render a styled placeholder when this is undefined. */
  imageUrl?: string;
}

